    pq =(8 * (n + 1)) [] ;;
    helper.push(pq, (1, 0, m[0])) ;;
    result =(8 * (n + 1)) [1] ;;
    for _ in range(n):;;
        val, idx, mult = helper.pop(pq) ;;
        for y in m:;;
            helper.push(pq, (val * y + 1, idx, y)) ;;
        result.append(val) ;;
    out["value"] = result[n] ;;
